import{_ as t,c as r,o as i,ag as e}from"./chunks/framework.C86mscM5.js";const m=JSON.parse('{"title":"JFrog Artifactory","description":"","frontmatter":{},"headers":[],"relativePath":"devops/registries/artifactory.md","filePath":"devops/registries/artifactory.md","lastUpdated":1788689791000}'),o={name:"devops/registries/artifactory.md"};function s(l,a,n,p,c,d){return i(),r("div",null,a[0]||(a[0]=[e('<h1 id="jfrog-artifactory" tabindex="-1">JFrog Artifactory <a class="header-anchor" href="#jfrog-artifactory" aria-label="Permalink to &quot;JFrog Artifactory&quot;">​</a></h1><p>JFrog Artifactory 是支持多种包格式和通用文件的制品仓库管理器，可用于代理外部软件源、托管内部制品，并在多个环境或区域之间分发经过验证的构建产物。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><strong>remote repository</strong>：代理并缓存外部软件源。</li><li><strong>local repository</strong>：保存组织内部构建和发布的制品。</li><li><strong>virtual repository</strong>：将多个 remote 和 local 仓库组合成统一入口。</li></ul><p>开发环境和 CI 通常从 virtual repository 下载依赖，发布流水线则把制品上传到用途明确的 local repository。</p><h2 id="npm-使用方式" tabindex="-1">npm 使用方式 <a class="header-anchor" href="#npm-使用方式" aria-label="Permalink to &quot;npm 使用方式&quot;">​</a></h2><p>将项目的下载地址指向 npm virtual repository：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">registry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://artifactory.example.com/artifactory/api/npm/npm-virtual/</span></span></code></pre></div><p>发布私有包时使用对应的 local repository，并通过流水线的密钥管理能力注入访问令牌。不要在 <code>.npmrc</code> 或流水线配置中保存明文凭据。</p><h2 id="生产建议" tabindex="-1">生产建议 <a class="header-anchor" href="#生产建议" aria-label="Permalink to &quot;生产建议&quot;">​</a></h2><ul><li>按包格式、团队或生命周期划分仓库，避免开发快照与正式制品混放。</li><li>对正式版本启用不可覆盖策略，并保留发布人、来源 Commit 和构建记录。</li><li>根据风险要求评估高可用、跨区域复制、制品签名和安全扫描能力。</li><li>为缓存、属性元数据和二进制文件制定一致的备份与恢复方案。</li><li>配置保留策略清理过期快照，同时保护仍被生产环境引用的制品。</li></ul><p>Artifactory 的扩展能力较多，但部分治理、安全和高可用能力可能与产品版本或许可证有关。选型时应先验证所需功能和总体维护成本。</p>',12)]))}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
